export function crackerRecipesForWeek(week: number): CrackerRecipeWeek {
  const w = Math.min(6, Math.max(1, Math.floor(week) || 1));
  return CRACKER_RECIPE_WEEKS[w - 1] ?? CRACKER_RECIPE_WEEKS[0];
}

export function crackerRecipeById(week: number, day: number, meal: CrackerMeal): CrackerRecipe | undefined {
  return crackerRecipesForWeek(week).recipes.find((r) => r.day === day && r.meal === meal);
}

